let state = "closed";
let failures = 0;
let openedAt = 0;

function call(now, up) {
  if (state === "open") {
    if (now - openedAt < 5000) return "fast fail";
    state = "half-open";
  }
  if (up) {
    state = "closed";
    failures = 0;
    return "ok";
  }
  failures += 1;
  if (state === "half-open" || failures >= 2) {
    state = "open";
    openedAt = now;
  }
  return "503";
}

console.log(call(0, false), call(1, false), call(2, true), call(6000, false), call(6001, true));

function wait(ms, value) {
  return new Promise((resolve) => setTimeout(() => resolve(value), ms));
}

function withTimeout(promise, ms) {
  const timeout = new Promise((_, reject) => setTimeout(() => reject(new Error("timed out")), ms));
  return Promise.race([promise, timeout]);
}

for (const [name, ms] of [["mug", 5], ["lamp", 80]]) {
  try {
    console.log(name, await withTimeout(wait(ms, "7 in stock"), 30));
  } catch (error) {
    console.log(name, error.message);
  }
}

function shouldRetry(request, status) {
  const transient = [429, 502, 503, 504].includes(status);
  const safe = ["GET", "HEAD", "PUT"].includes(request.method) || Boolean(request.idempotencyKey);
  return transient && safe;
}

console.log(shouldRetry({ method: "POST" }, 503));
console.log(shouldRetry({ method: "POST", idempotencyKey: "k1" }, 503));
console.log(shouldRetry({ method: "GET" }, 404));

const deadLetter = [];

async function runJob(job, handler) {
  for (let attempt = 1; attempt <= job.attempts; attempt++) {
    try {
      await handler(job, attempt);
      return `done on attempt ${attempt}`;
    } catch {}
  }
  deadLetter.push(job.name);
  return "failed";
}

const flaky = async (job, attempt) => { if (attempt < 3) throw new Error("mail down"); };
console.log(await runJob({ name: "receipt-1", attempts: 5 }, flaky));
console.log(await runJob({ name: "receipt-2", attempts: 2 }, flaky));
console.log(deadLetter);

